137	void Monitor::createLayerSurface() {
138	  m_waylandSurface = wl_compositor_create_surface(m_daemon.getCompositor());
139	  assert(m_waylandSurface);
140	  auto input_region = wl_compositor_create_region(m_daemon.getCompositor());
141	  assert(input_region);
142	  wl_surface_set_input_region(m_waylandSurface, input_region);
143	  wl_region_destroy(input_region);
144	
145	  if (m_daemon.hasFractionScaleManager()) {
146	    m_fractionalScale = wp_fractional_scale_manager_v1_get_fractional_scale(
147	        m_daemon.getFractionalScaleManager(), m_waylandSurface);
148	    wp_fractional_scale_v1_add_listener(m_fractionalScale,
149	                                        &fract_scale_listener, this);
150	
151	    if (m_daemon.getViewporter() != nullptr) {
152	      m_viewport = wp_viewporter_get_viewport(m_daemon.getViewporter(),
153	                                              m_waylandSurface);
154	    }
155	  }
156	  m_layerSurface = zwlr_layer_shell_v1_get_layer_surface(
157	      m_daemon.getLayerShell(), m_waylandSurface, m_waylandOutput,
158	      ZWLR_LAYER_SHELL_V1_LAYER_BACKGROUND, "yin-wallpaper");
159	  zwlr_layer_surface_v1_set_size(m_layerSurface, 0, 0);
160	  zwlr_layer_surface_v1_set_anchor(m_layerSurface,
161	                                   ZWLR_LAYER_SURFACE_V1_ANCHOR_TOP |
162	                                       ZWLR_LAYER_SURFACE_V1_ANCHOR_RIGHT |
163	                                       ZWLR_LAYER_SURFACE_V1_ANCHOR_BOTTOM |
164	                                       ZWLR_LAYER_SURFACE_V1_ANCHOR_LEFT);
165	  zwlr_layer_surface_v1_set_exclusive_zone(m_layerSurface, -1);
166	
167	  zwlr_layer_surface_v1_add_listener(m_layerSurface, &layer_surface_listener,
168	                                     this);
169	  wl_surface_commit(m_waylandSurface);
170	}
