200	void Monitor::resizeEGL() {
201	  setBufferSize();
202	  if (m_viewport) {
203	    wp_viewport_set_destination(m_viewport, m_width, m_height);
204	  } else {
205	    wl_surface_set_buffer_scale(m_waylandSurface, m_scale);
206	  }
207	  if (m_daemon.m_eglDisplay == EGL_NO_DISPLAY ||
208	      m_daemon.m_eglContext == EGL_NO_CONTEXT) {
209	    throw std::runtime_error("OpenGL renderer is not bound");
210	  }
211	  if (m_eglWindow == nullptr) {
212	    m_eglWindow =
213	        wl_egl_window_create(m_waylandSurface, static_cast<int>(m_bufferWidth),
214	                             static_cast<int>(m_bufferHeight));
215	    if (m_eglWindow == nullptr) {
216	      throw std::runtime_error("wl_egl_window_create failed");
217	    }
218	  } else {
219	    wl_egl_window_resize(m_eglWindow, static_cast<int>(m_bufferWidth),
220	                         static_cast<int>(m_bufferHeight), 0, 0);
221	  }
222	
223	  if (m_eglSurface == EGL_NO_SURFACE) {
224	    m_eglSurface = eglCreateWindowSurface(
225	        m_daemon.m_eglDisplay, m_daemon.m_eglConfig,
226	        reinterpret_cast<EGLNativeWindowType>(m_eglWindow), nullptr);
227	    if (m_eglSurface == EGL_NO_SURFACE) {
228	      throw std::runtime_error("eglCreateWindowSurface failed");
229	    }
230	  }
231	
232	  if (eglMakeCurrent(m_daemon.m_eglDisplay, m_eglSurface, m_eglSurface,
233	                     m_daemon.m_eglContext) != EGL_TRUE) {
234	    throw std::runtime_error("eglMakeCurrent failed during resize");
235	  }
236	  glViewport(0, 0, static_cast<GLsizei>(m_bufferWidth),
237	             static_cast<GLsizei>(m_bufferHeight));
238	
239	  if (eglSwapBuffers(m_daemon.m_eglDisplay, m_eglSurface) != EGL_TRUE) {
240	    std::cout << eglGetError() << std::endl;
241	    throw std::runtime_error("eglSwapBuffers failed");
242	  }
243	}
244	
245	void Monitor::render() {
246	  if (eglMakeCurrent(m_daemon.m_eglDisplay, m_eglSurface, m_eglSurface,
247	                     m_daemon.m_eglContext) != EGL_TRUE) {
248	    throw std::runtime_error("eglMakeCurrent failed ");
249	  }
250	  glViewport(0, 0, static_cast<GLsizei>(m_bufferWidth),
251	             static_cast<GLsizei>(m_bufferHeight));
252	
253	  // destory old egl images, this is safe to do even if the images are null for
254	  // some reason
255	  for (int i = 0; i < 2; ++i) {
256	    if (m_eglImages[i] != EGL_NO_IMAGE) {
257	      m_daemon.eglDestroyImageKHR(m_daemon.m_eglDisplay, m_eglImages[i]);
258	      m_eglImages[i] = EGL_NO_IMAGE;
259	    }
260	  }
261	
262	  bool startTransition = false;
263	
264	  // Kickoff transition if :
265	  // This is the very first frame of the video/image being rendered
266	  // There is a previous texture to transition from
267	  // Transitions are enabled
268	  // There is no active transition
269	  if (m_isFirstAnimationFrame && m_hasPreviousFrame && m_useTransitions &&
270	      !m_transitionState) {
271	    startTransition = true;
272	    m_renderIntoTempTexture = true;
273	  }
274	  if (m_transitionState != nullptr) {
275	    resumeTransition();
276	    return;
277	  }
278	
279	  m_isFirstAnimationFrame = false;
280	  if (!m_wallpaper->m_isSingleFrame && !m_wallpaper->decodeNextFrame())
281	    return;
282	  if (m_wallpaper->m_frame->format == AV_PIX_FMT_VAAPI) {
283	    renderVAAPI();
284	  } else if (m_wallpaper->m_frame->format == AV_PIX_FMT_CUDA) {
285	#ifdef ENABLE_CUDA
286	    renderCUDACopy();
287	#endif
288	  } else if (m_wallpaper->m_frame->format == AV_PIX_FMT_NV12) {
289	    renderSoftwareNV12();
290	  }
291	
292	  m_hasPreviousFrame = true;
293	  if (startTransition) {
294	    startTransition = false;
295	    m_renderIntoTempTexture = false;
296	    m_transitionState = std::make_unique<TransitionState>();
297	  }
298	}
