637	Monitor::setWallpaper(std::string img_path,
638	                      std::optional<std::string> transition) {
639	  // reset state
640	  m_wallpaper = std::make_unique<Wallpaper>();
641	  m_wallpaperPlaying = true;
642	  m_isFirstAnimationFrame = true;
643	  m_useTransitions = false;
644	  m_requiredTransitionShaderProgram = {};
645	  if (transition.has_value()) {
646	    auto trans = *transition;
647	    m_useTransitions = true;
648	    if (m_transitionShaderPrograms.contains(trans)) {
649	      m_requiredTransitionShaderProgram = m_transitionShaderPrograms[trans];
650	    } else {
651	      // just ignore
652	      m_useTransitions = false;
653	    }
654	  }
655	  auto error = m_wallpaper->bind(img_path, m_daemon.m_vaDisplay,
656	                                 m_daemon.m_hardwareAccelerationBackend);
657	  if (error == Success) {
658	    m_nextVideoFrame = std::chrono::steady_clock::now();
659	    m_wallpaperID++;
660	    // Record against this monitor, and as the fallback for monitors we have
661	    // not seen before.
662	    std::filesystem::create_directories(yinCacheDir());
663	    for (const auto &file_path : {historyFile(), lastWallpaperFile()}) {
664	      std::ofstream cachefile(file_path);
665	      cachefile << img_path;
666	    }
667	    // start playback
668	    nextFrame();
669	  } else {
670	    m_wallpaper = nullptr;
671	  }
672	  return error;
673	}
