682	void Monitor::onFrame(u32 scheduledID) {
683	  if (scheduledID != m_wallpaperID || m_wallpaper == nullptr)
684	    return;
685	  auto now = std::chrono::steady_clock::now();
686	  auto diff = std::chrono::duration_cast<std::chrono::milliseconds>(
687	                  now - m_nextVideoFrame)
688	                  .count();
689	  // incase the compositor sends us to sleep
690	  if (diff > 100) {
691	    m_nextVideoFrame = now;
692	  }
693	  if (now >= m_nextVideoFrame && m_wallpaper != nullptr) {
694	    m_nextVideoFrame += m_wallpaper->m_frameDuration;
695	    render();
696	  }
697	  // don't render again if we have a single image unless we are in a transition
698	  if ((m_wallpaper->m_isSingleFrame && m_transitionState == nullptr) ||
699	      m_wallpaperPlaying == false)
700	    return;
701	  nextFrame();
702	}
