855	void Monitor::setPlayPause(bool play) {
856	  if (play && !m_wallpaperPlaying) {
857	    m_nextVideoFrame =
858	        std::chrono::steady_clock::now() + m_wallpaper->m_frameDuration;
859	    nextFrame();
860	  }
861	  m_wallpaperPlaying = play;
862	}
863	WallpaperBindError Monitor::restoreWallpaper() {
864	  auto record = readWallpaperRecord(historyFile());
865	  if (!record) {
866	    record = readWallpaperRecord(lastWallpaperFile());
867	  }
868	  if (!record) {
869	    return NoHistory;
870	  }
871	  return setWallpaper(*record, std::nullopt);
872	}
873	
874	// Runs once per output, as soon as its surface is drawable. A monitor that
875	// just appeared gets the last wallpaper on its own; one that already has a
876	// wallpaper is left alone.
877	void Monitor::onSurfaceReady() {
878	  if (m_wallpaper != nullptr)
879	    return;
880	  auto error = restoreWallpaper();
881	  switch (error) {
882	  case Success:
883	    std::cout << "[yin] " << m_name << ": applied wallpaper on connect"
884	              << std::endl;
885	    break;
886	  case NoHistory:
887	    std::cout << "[yin] " << m_name
888	              << ": no wallpaper recorded yet, leaving blank" << std::endl;
889	    break;
890	  default:
891	    std::cout << "[yin] " << m_name
892	              << ": could not apply wallpaper on connect (error "
893	              << static_cast<int>(error) << ")" << std::endl;
894	    break;
895	  }
896	}
