15	  unlink(SOCKET_PATH);
16	  m_serverFd = socket(AF_UNIX, SOCK_STREAM, 0);
17	  if (m_serverFd == -1) {
18	    throw std::runtime_error("Could not start IPC server");
19	  }
20	
21	  sockaddr_un addr{};
22	  addr.sun_family = AF_UNIX;
23	  strncpy(addr.sun_path, SOCKET_PATH, sizeof(addr.sun_path) - 1);
24	
25	  if (bind(m_serverFd, reinterpret_cast<sockaddr *>(&addr), sizeof(addr)) ==
26	      -1) {
27	    throw std::runtime_error("Could not start IPC server");
28	  }
29	
30	  if (listen(m_serverFd, 5) == -1) {
31	    throw std::runtime_error("Could not start IPC server");
32	  }
33	}
