  fds[1].events = POLLIN;
  while (true) {
    {
      wl_display_flush(m_waylandDisplay);
    }
    int _ = poll(fds, 2, -1);
    if ((fds[0].revents & POLLIN) != 0) {
      wl_display_dispatch(m_waylandDisplay);
