36	void IPC::serverAccept(Daemon &daemon) {
37	  int client = accept(m_serverFd, nullptr, nullptr);
38	  char buffer[1024];
39	  ssize_t bytes = ::read(client, buffer, sizeof(buffer));
40	  char bad_video_message[] =
41	      "Problem with video file, please delete ~/cache/yin and try again";
42	  char no_hardware_decoding[] =
43	      "Hardware decoding is unavailable, cannot proceed"; // maybe we can,
44	                                                          // we'll find out
45	  char no_history[] = "No wallpaper previously set on this monitor";
46	  char success_message[] = "Img sent to daemon!";
47	  if (bytes > 0) {
48	    auto message = DeserializeMessage(buffer, bytes);
49	    if (std::holds_alternative<MonitorSizeMessage>(message)) {
50	      auto mes = std::get<MonitorSizeMessage>(message);
51	
52	      if (auto *monitor = daemonFindMonitor(daemon, mes.monitor)) {
53	        std::string dimensions = std::to_string(monitor->m_bufferWidth) + "x" +
54	                                 std::to_string(monitor->m_bufferHeight);
55	
56	        write(client, dimensions.data(), dimensions.size());
57	      }
58	    } else if (std::holds_alternative<SetWallpaperMessage>(message)) {
59	      auto mes = std::get<SetWallpaperMessage>(message);
60	
61	      auto monitor = daemonFindMonitor(daemon, mes.monitor);
62	      auto error = monitor->setWallpaper(mes.imgPath, mes.transition);
63	
64	
65	      if (error == BadVideo) {
66	        write(client, bad_video_message, std::strlen(bad_video_message));
67	      }
68	      if (error == NoHarwareDecoding) {
69	        write(client, no_hardware_decoding, std::strlen(no_hardware_decoding));
70	      }
71	      if (error == Success) {
72	        write(client, success_message, std::strlen(success_message));
73	      }
74	    } else if (std::holds_alternative<PlayPauseMessage>(message)) {
75	      auto mes = std::get<PlayPauseMessage>(message);
76	      auto monitor = daemonFindMonitor(daemon, mes.monitor);
77	      monitor->setPlayPause(mes.play);
78	    } else if (std::holds_alternative<RestoreMessage>(message)) {
79	      auto mes = std::get<RestoreMessage>(message);
80	      auto monitor = daemonFindMonitor(daemon, mes.monitor);
81	      auto error = monitor->restoreWallpaper();
82	      if (error == BadVideo) {
83	        write(client, bad_video_message, std::strlen(bad_video_message));
84	      }
85	      if (error == NoHarwareDecoding) {
86	        write(client, no_hardware_decoding, std::strlen(no_hardware_decoding));
87	      }
88	      if (error == Success) {
89	        write(client, success_message, std::strlen(success_message));
90	      }
91	      if (error == NoHistory) {
92	        write(client, no_history, std::strlen(no_history));
93	      }
94	    }
95	  }
96	  close(client);
97	}
