99	Monitor *IPC::daemonFindMonitor(Daemon &daemon,
100	                                const std::optional<std::string> &monitorName) {
101	  if (!monitorName.has_value()) {
102	    return daemon.m_monitors.empty() ? nullptr
103	                                     : daemon.m_monitors.front().get();
104	  }
105	
106	  for (auto &monitor : daemon.m_monitors) {
107	    if (monitor->m_name == *monitorName) {
108	      return monitor.get();
109	    }
110	  }
111	  return nullptr;
112	}
