39	void Daemon::initWayland() {
40	  m_waylandDisplay = wl_display_connect(NULL);
41	  if (m_waylandDisplay == nullptr) {
42	    throw std::runtime_error("Could not connect to a Wayland Compositor");
43	  }
44	  createEGL();
45	  if (m_hardwareAccelerationBackend == Vaapi) {
46	    m_vaDisplay = vaGetDisplayWl(m_waylandDisplay);
47	    assert(m_vaDisplay != nullptr);
48	  }
49	  int major, minor;
50	  auto wl_registry = wl_display_get_registry(m_waylandDisplay);
51	  wl_registry_add_listener(wl_registry, &registry_listener, this);
52	  if (wl_display_roundtrip(m_waylandDisplay) < 0) {
53	    throw std::runtime_error("Failed to roundtrip wayland display");
54	  }
55	  if (m_hardwareAccelerationBackend == Vaapi) {
56	    if (vaInitialize(m_vaDisplay, &major, &minor) != VA_STATUS_SUCCESS) {
57	      throw std::runtime_error("Failed to init VA display");
58	    }
59	  }
60	  ensureGlobals();
61	}
