63	void Daemon::bindGlobal(struct wl_registry *registry, uint32_t name,
64	                        const char *interface, uint32_t version) {
65	  if (std::strcmp(interface, wl_compositor_interface.name) == 0) {
66	    m_waylandCompositor = static_cast<wl_compositor *>(
67	        wl_registry_bind(registry, name, &wl_compositor_interface, 4));
68	  }
69	  // if (std::strcmp(interface, wl_shm_interface.name) == 0) {
70	  //   m_waylandSharedMemory = static_cast<wl_shm *>(
71	  //       wl_registry_bind(registry, name, &wl_shm_interface, 1));
72	  // }
73	  if (std::strcmp(interface, zwlr_layer_shell_v1_interface.name) == 0) {
74	    m_layerShell = static_cast<zwlr_layer_shell_v1 *>(
75	        wl_registry_bind(registry, name, &zwlr_layer_shell_v1_interface, 1));
76	  }
77	  if (std::strcmp(interface, wl_output_interface.name) == 0) {
78	    auto wl_output = static_cast<struct wl_output *>(
79	        wl_registry_bind(registry, name, &wl_output_interface, 4));
80	    auto monitor = std::make_unique<Monitor>(wl_output, *this);
81	    m_monitors.push_back(std::move(monitor));
82	  }
83	  if (std::strcmp(interface, wp_fractional_scale_manager_v1_interface.name) ==
84	      0) {
85	    m_fractionalScaleManager =
86	        static_cast<wp_fractional_scale_manager_v1 *>(wl_registry_bind(
87	            registry, name, &wp_fractional_scale_manager_v1_interface, 1));
88	  }
89	  if (std::strcmp(interface, wp_viewporter_interface.name) == 0) {
90	    m_waylandViewporter = static_cast<wp_viewporter *>(
91	        wl_registry_bind(registry, name, &wp_viewporter_interface, 1));
92	  }
93	}
