101	void Daemon::run() {
102	  auto ipc = IPC{};
103	  ipc.serverCreate();
104	  int wl_fd = wl_display_get_fd(m_waylandDisplay);
105	  struct pollfd fds[2];
106	  fds[0].fd = wl_fd;
107	  fds[0].events = POLLIN;
108	
109	  fds[1].fd = ipc.m_serverFd;
110	  fds[1].events = POLLIN;
111	  while (true) {
112	    {
113	      wl_display_flush(m_waylandDisplay);
114	    }
115	    int _ = poll(fds, 2, -1);
116	    if ((fds[0].revents & POLLIN) != 0) {
117	      wl_display_dispatch(m_waylandDisplay);
118	    }
119	    if ((fds[1].revents & POLLIN) != 0) {
120	      ipc.serverAccept(*this);
121	    }
122	  }
123	}
