137	void Daemon::createEGL() {
138	  m_eglDisplay =
139	      eglGetDisplay(reinterpret_cast<EGLNativeDisplayType>(m_waylandDisplay));
140	  if (m_eglDisplay == EGL_NO_DISPLAY) {
141	    throw std::runtime_error("eglGetDisplay failed");
142	  }
143	
144	  EGLint major = 0;
145	  EGLint minor = 0;
146	  if (eglInitialize(m_eglDisplay, &major, &minor) != EGL_TRUE) {
147	    throw std::runtime_error("eglInitialize failed");
148	  }
149	
150	  if (eglBindAPI(EGL_OPENGL_API) != EGL_TRUE) {
151	    throw std::runtime_error("eglBindAPI failed");
152	  }
153	
154	  constexpr EGLint kConfigAttributes[] = {
155	      EGL_SURFACE_TYPE,
156	      EGL_WINDOW_BIT,
157	      EGL_RENDERABLE_TYPE,
158	      EGL_OPENGL_ES2_BIT,
159	      EGL_RED_SIZE,
160	      8,
161	      EGL_GREEN_SIZE,
162	      8,
163	      EGL_BLUE_SIZE,
164	      8,
165	      EGL_ALPHA_SIZE,
166	      0,
167	      EGL_NONE,
168	  };
169	
170	  constexpr EGLint kContextAttributes[] = {
171	      EGL_CONTEXT_CLIENT_VERSION,
172	      2,
173	      EGL_NONE,
174	  };
175	  EGLint configCount = 0;
176	  if (eglChooseConfig(m_eglDisplay, kConfigAttributes, &m_eglConfig, 1,
177	                      &configCount) != EGL_TRUE ||
178	      configCount != 1) {
179	    throw std::runtime_error("eglChooseConfig failed");
180	  }
181	
182	  m_eglContext = eglCreateContext(m_eglDisplay, m_eglConfig, EGL_NO_CONTEXT,
183	                                  kContextAttributes);
184	  if (m_eglContext == EGL_NO_CONTEXT) {
185	    throw std::runtime_error("eglCreateContext failed");
186	  }
187	
188	  // locate gl procs
189	  eglCreateImageKHR = reinterpret_cast<PFNEGLCREATEIMAGEKHRPROC>(
190	      eglGetProcAddress("eglCreateImageKHR"));
191	  eglDestroyImageKHR = reinterpret_cast<PFNEGLDESTROYIMAGEKHRPROC>(
192	      eglGetProcAddress("eglDestroyImageKHR"));
193	  glEGLImageTargetTexture2DOES =
194	      reinterpret_cast<PFNGLEGLIMAGETARGETTEXTURE2DOESPROC>(
195	          eglGetProcAddress("glEGLImageTargetTexture2DOES"));
196	  glGenVertexArrays = reinterpret_cast<PFNGLGENVERTEXARRAYSPROC>(
197	      eglGetProcAddress("glGenVertexArrays"));
198	  glBindVertexArray = reinterpret_cast<PFNGLBINDVERTEXARRAYPROC>(
199	      eglGetProcAddress("glBindVertexArray"));
200	  glCopyImageSubData = reinterpret_cast<PFNGLCOPYIMAGESUBDATAPROC>(
201	      eglGetProcAddress("glCopyImageSubData"));
202	  if (!eglCreateImageKHR || !eglDestroyImageKHR ||
203	      !glEGLImageTargetTexture2DOES || !glBindVertexArray ||
204	      !glGenVertexArrays || !glCopyImageSubData) {
205	    throw std::runtime_error("Missing GL procs");
206	  }
207	}
