356	void Monitor::stageNV12Buffers(u32 width, u32 height) {
357	
358	  // do not reset m_textures when we are not rendering into it, or VAAPI ->
359	  // Software transitions will be broken
360	  if (!m_renderIntoTempTexture) {
361	    glBindTexture(GL_TEXTURE_2D, m_textures[0]);
362	    glTexImage2D(GL_TEXTURE_2D, 0, GL_R8, width, height, 0, GL_RED,
363	                 GL_UNSIGNED_BYTE, nullptr);
364	    glBindTexture(GL_TEXTURE_2D, m_textures[1]);
365	    glTexImage2D(GL_TEXTURE_2D, 0, GL_RG8, width / 2, height / 2, 0, GL_RG,
366	                 GL_UNSIGNED_BYTE, nullptr);
367	  }
368	
369	  glBindTexture(GL_TEXTURE_2D, m_toTextures[0]);
370	  glTexImage2D(GL_TEXTURE_2D, 0, GL_R8, width, height, 0, GL_RED,
371	               GL_UNSIGNED_BYTE, nullptr);
372	  glBindTexture(GL_TEXTURE_2D, m_toTextures[1]);
373	  glTexImage2D(GL_TEXTURE_2D, 0, GL_RG8, width / 2, height / 2, 0, GL_RG,
374	               GL_UNSIGNED_BYTE, nullptr);
375	
376	  glBindTexture(GL_TEXTURE_2D, 0);
377	  if ((m_hostY.size() == static_cast<size_t>(width) * height) &&
378	      (m_hostUV.size() == static_cast<size_t>(width) * (height / 2))) {
379	    return;
380	  }
381	  m_hostY.resize(static_cast<size_t>(width) * height);
382	  m_hostUV.resize(static_cast<size_t>(width) * (height / 2));
383	}
