525	void Monitor::renderVAAPI() {
526	  VASurfaceID va_surface = (uintptr_t)m_wallpaper->m_frame->data[3];
527	  VADRMPRIMESurfaceDescriptor prime;
528	  if (vaExportSurfaceHandle(m_daemon.m_vaDisplay, va_surface,
529	                            VA_SURFACE_ATTRIB_MEM_TYPE_DRM_PRIME_2,
530	                            VA_EXPORT_SURFACE_READ_ONLY |
531	                                VA_EXPORT_SURFACE_SEPARATE_LAYERS,
532	                            &prime) != VA_STATUS_SUCCESS) {
533	    std::cout << "vaExportSurfaceHandle failed";
534	  }
535	  if (prime.fourcc != VA_FOURCC_NV12) {
536	    std::cout << "export format check failed";
537	    ; // we only support NV12 here
538	  }
539	  vaSyncSurface(m_daemon.m_vaDisplay, va_surface);
540	  float texcoord_x1 = 1.0f, texcoord_y1 = 1.0f;
541	  texcoord_x1 =
542	      (float)((double)m_wallpaper->m_codecContext->width / (double)prime.width);
543	  texcoord_y1 = (float)((double)m_wallpaper->m_codecContext->height /
544	                        (double)prime.height);
545	  glUseProgram(m_glShaderProgram);
546	  glUniform2f(glGetUniformLocation(m_glShaderProgram, "uTexCoordScale"),
547	              texcoord_x1, texcoord_y1);
548	  m_lastTextCoordScaleX = texcoord_x1;
549	  m_lastTextCoordScaleY = texcoord_y1;
550	
551	  for (int i = 0; i < 2; ++i) {
552	    static const uint32_t formats[2] = {DRM_FORMAT_R8, DRM_FORMAT_GR88};
553	#define LAYER i
554	#define PLANE 0
555	    if (prime.layers[i].drm_format != formats[i]) {
556	      throw std::runtime_error("expected DRM format check");
557	    }
558	    EGLint img_attr[] = {
559	        EGL_LINUX_DRM_FOURCC_EXT,
560	        static_cast<EGLint>(formats[i]),
561	        EGL_WIDTH,
562	        static_cast<EGLint>(prime.width / (i + 1)), // half size
563	        EGL_HEIGHT,
564	        static_cast<EGLint>(prime.height / (i + 1)), // for chroma
565	        EGL_DMA_BUF_PLANE0_FD_EXT,
566	        prime.objects[prime.layers[LAYER].object_index[PLANE]].fd,
567	        EGL_DMA_BUF_PLANE0_OFFSET_EXT,
568	        static_cast<EGLint>(prime.layers[LAYER].offset[PLANE]),
569	        EGL_DMA_BUF_PLANE0_PITCH_EXT,
570	        static_cast<EGLint>(prime.layers[LAYER].pitch[PLANE]),
571	        EGL_NONE};
572	    m_eglImages[i] =
573	        m_daemon.eglCreateImageKHR(m_daemon.m_eglDisplay, EGL_NO_CONTEXT,
574	                                   EGL_LINUX_DMA_BUF_EXT, NULL, img_attr);
575	    if (!m_eglImages[i]) {
576	      throw std::runtime_error(i ? "chroma eglCreateImageKHR"
577	                                 : "luma eglCreateImageKHR");
578	    }
579	    glActiveTexture(GL_TEXTURE0 + i);
580	    glBindTexture(GL_TEXTURE_2D, m_renderIntoTempTexture == true
581	                                     ? m_toTextures[i]
582	                                     : m_textures[i]);
583	    while (glGetError()) {
584	    }
585	    m_daemon.glEGLImageTargetTexture2DOES(GL_TEXTURE_2D, m_eglImages[i]);
586	    if (glGetError()) {
587	      throw std::runtime_error("glEGLImageTargetTexture2DOES");
588	    }
589	  }
590	
591	  for (int i = 0; i < (int)prime.num_objects; ++i) {
592	    close(prime.objects[i].fd);
593	  }
594	  if (!m_renderIntoTempTexture) {
595	    // draw
596	    glClear(GL_COLOR_BUFFER_BIT);
597	    m_daemon.glBindVertexArray(m_VAO);
598	    glDrawElements(GL_TRIANGLES, 6, GL_UNSIGNED_INT, 0);
599	
600	    if (eglSwapBuffers(m_daemon.m_eglDisplay, m_eglSurface) != EGL_TRUE) {
601	      std::cout << eglGetError() << std::endl;
602	      throw std::runtime_error("eglSwapBuffers failed");
603	    }
604	  }
605	}
