622	// Reads a wallpaper path out of a cache file, rejecting it when the file is
623	// empty or names something that no longer exists on disk.
624	static std::optional<std::string>
625	readWallpaperRecord(const std::filesystem::path &path) {
626	  std::ifstream file(path);
627	  if (!file.is_open())
628	    return std::nullopt;
629	  std::string line;
630	  if (!std::getline(file, line) || line.empty())
