675	void Monitor::nextFrame() {
676	  auto *cb = wl_surface_frame(m_waylandSurface);
677	  auto cbData = new FrameCallbackData{this, m_wallpaperID};
678	  wl_callback_add_listener(cb, &frame_listener, cbData);
679	  wl_surface_commit(m_waylandSurface);
680	}
