729	void Monitor::setupGl() {
730	  if (eglMakeCurrent(m_daemon.m_eglDisplay, m_eglSurface, m_eglSurface,
731	                     m_daemon.m_eglContext) != EGL_TRUE) {
732	    throw std::runtime_error("eglMakeCurrent failed during resize");
733	  }
734	  glViewport(0, 0, static_cast<GLsizei>(m_bufferWidth),
735	             static_cast<GLsizei>(m_bufferHeight));
736	
737	  // full sized rectangle
738	  float vertices[] = {-1.f, 1.f,  0.f, 0.f, 0.f, -1.f, -1.f, 0.f, 0.f, 1.f,
739	                      1.f,  -1.f, 0.f, 1.f, 1.f, 1.f,  1.f,  0.f, 1.f, 0.f};
740	
741	  u32 indices[] = {0, 1, 2, 2, 3, 0};
742	
743	  uint32_t VAO;
744	  m_daemon.glGenVertexArrays(1, &VAO);
745	  m_daemon.glBindVertexArray(VAO);
746	  m_VAO = VAO;
747	
748	  u32 VBO;
749	  glGenBuffers(1, &VBO);
750	  glBindBuffer(GL_ARRAY_BUFFER, VBO);
751	  glBufferData(GL_ARRAY_BUFFER, sizeof(vertices), vertices, GL_STATIC_DRAW);
752	
753	  u32 EBO;
754	  glGenBuffers(1, &EBO);
755	  glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, EBO);
756	  glBufferData(GL_ELEMENT_ARRAY_BUFFER, sizeof(indices), indices,
757	               GL_STATIC_DRAW);
758	
759	  u32 vertexShader;
760	  vertexShader = glCreateShader(GL_VERTEX_SHADER);
761	  glShaderSource(vertexShader, 1, &vertexShaderSourceMain, NULL);
762	  glCompileShader(vertexShader);
763	  {
764	
765	    GLint success;
766	    char infoLog[512];
767	
768	    glGetShaderiv(vertexShader, GL_COMPILE_STATUS, &success);
769	    if (!success) {
770	      glGetShaderInfoLog(vertexShader, 512, nullptr, infoLog);
771	      std::cout << infoLog << std::endl;
772	    }
773	  }
774	  u32 fragmentShader;
775	  fragmentShader = glCreateShader(GL_FRAGMENT_SHADER);
776	  glShaderSource(fragmentShader, 1, &fragmentShaderSourceMain, NULL);
777	  glCompileShader(fragmentShader);
778	  {
779	    GLint success;
780	    char infoLog[512];
781	
782	    glGetShaderiv(fragmentShader, GL_COMPILE_STATUS, &success);
783	    if (!success) {
784	      glGetShaderInfoLog(fragmentShader, 512, nullptr, infoLog);
785	      std::cout << infoLog << std::endl;
786	    }
787	  }
788	  m_glShaderProgram = glCreateProgram();
789	  glAttachShader(m_glShaderProgram, vertexShader);
790	  glAttachShader(m_glShaderProgram, fragmentShader);
791	  glLinkProgram(m_glShaderProgram);
792	
793	  compileTransitionShaders(vertexShader);
794	  glDeleteShader(vertexShader);
795	  glDeleteShader(fragmentShader);
796	
797	  glUseProgram(m_glShaderProgram);
798	  glUniform1i(glGetUniformLocation(m_glShaderProgram, "uTexY"), 0);
799	  glUniform1i(glGetUniformLocation(m_glShaderProgram, "uTexC"), 1);
800	
801	  glVertexAttribPointer(0, 3, GL_FLOAT, GL_FALSE, 5 * sizeof(float), (void *)0);
802	  glEnableVertexAttribArray(0);
803	  glVertexAttribPointer(1, 2, GL_FLOAT, GL_FALSE, 5 * sizeof(float),
804	                        (void *)(3 * sizeof(float)));
805	  glEnableVertexAttribArray(1);
806	
807	  // texture
808	  glGenTextures(2, m_textures);
809	  glGenTextures(2, m_toTextures);
810	  for (int i = 0; i < 2; ++i) {
811	    glBindTexture(GL_TEXTURE_2D, m_textures[i]);
812	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
813	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
814	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
815	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
816	
817	    glBindTexture(GL_TEXTURE_2D, m_toTextures[i]);
818	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP_TO_EDGE);
819	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP_TO_EDGE);
820	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
821	    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
822	  }
823	  glBindTexture(GL_TEXTURE_2D, 0);
824	
825	  m_glSetup = true;
826	}
